  return sessions.fork(liveSource, void 0, newId);
}

/** 计算副本序号：-副本x，x 取最小可用正整数。 */
export function nextCopySuffix(base, existing) {
  let n = 1;
  while (existing.includes(`${base}-副本${n}`)) n += 1;
  return `${base}-副本${n}`;
}
